@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;

    @Transactional
    public PaymentResult charge(String idempotencyKey, ChargeRequest request) {
        return paymentRepository.findByIdempotencyKey(idempotencyKey)
                .map(PaymentEntity::toResult)
                .orElseGet(() -> {
                    PaymentEntity payment = new PaymentEntity(idempotencyKey, request.amount(), request.accountId());
                    // la contrainte UNIQUE(idempotency_key) fait échouer un doublon concurrent
                    paymentRepository.save(payment);
                    return payment.toResult();
                });
    }
}

